CREATE TABLE public.store_license (id integer PRIMARY KEY DEFAULT 1 CHECK (id=1), mode text NOT NULL DEFAULT 'demonstration' CHECK (mode IN ('demonstration','active','suspended')), monthly_price numeric(10,2) NOT NULL DEFAULT 65.90 CHECK (monthly_price>0), due_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, CHECK (mode <> 'active' OR due_at IS NOT NULL));
GRANT SELECT ON public.store_license TO authenticated; GRANT ALL ON public.store_license TO service_role;
ALTER TABLE public.store_license ENABLE ROW LEVEL SECURITY;
CREATE POLICY license_director_read ON public.store_license FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.platform_operators WHERE user_id=auth.uid()));
CREATE TABLE public.license_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, previous_state jsonb, next_state jsonb NOT NULL, reason text NOT NULL CHECK (length(reason) BETWEEN 5 AND 500), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.license_audit TO authenticated; GRANT ALL ON public.license_audit TO service_role;
ALTER TABLE public.license_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY license_audit_operator ON public.license_audit FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.platform_operators WHERE user_id=auth.uid()));
CREATE TABLE public.platform_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), license_id integer NOT NULL DEFAULT 1 REFERENCES public.store_license(id), amount numeric(10,2) NOT NULL CHECK (amount>0), currency text NOT NULL DEFAULT 'BRL' CHECK(currency='BRL'), due_at timestamptz NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','paid','cancelled')), method text CHECK(method IN ('pix','credit_card')), provider_payment_id text UNIQUE, external_reference uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.platform_invoices TO authenticated; GRANT ALL ON public.platform_invoices TO service_role;
ALTER TABLE public.platform_invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoice_director_read ON public.platform_invoices FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.platform_operators WHERE user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.license_allows_operation() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT mode='demonstration' OR (mode='active' AND due_at IS NOT NULL AND now()<due_at+interval '72 hours') FROM public.store_license WHERE id=1),false) $$;
REVOKE ALL ON FUNCTION public.license_allows_operation() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.license_allows_operation() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.assert_store_license() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.license_allows_operation() THEN RAISE EXCEPTION 'Estabelecimento em manutenção' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.assert_store_license() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.assert_store_license() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.configure_store_license(_mode text,_due timestamptz,_price numeric,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_row public.store_license; after_row public.store_license; BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_operators WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Acesso exclusivo FH Foods'; END IF; IF _mode NOT IN ('demonstration','active','suspended') OR _price<=0 OR _price>100000 OR length(trim(_reason)) NOT BETWEEN 5 AND 500 OR (_mode='active' AND _due IS NULL) THEN RAISE EXCEPTION 'Licença inválida'; END IF; SELECT * INTO before_row FROM public.store_license WHERE id=1 FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Licença não inicializada'; END IF; UPDATE public.store_license SET mode=_mode,due_at=_due,monthly_price=round(_price,2),updated_at=now(),updated_by=auth.uid() WHERE id=1 RETURNING * INTO after_row; INSERT INTO public.license_audit(actor_id,previous_state,next_state,reason) VALUES(auth.uid(),to_jsonb(before_row),to_jsonb(after_row),trim(_reason)); END $$;
REVOKE ALL ON FUNCTION public.configure_store_license(text,timestamptz,numeric,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.configure_store_license(text,timestamptz,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_licensed_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_store_license(); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_licensed_write() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['products','store_settings','coupons','orders','expenses','loyalty_accounts','dining_tables','waiter_calls','shared_carts','checkout_drafts','delivery_zones','club_plans','club_members','club_contract','order_reviews','print_jobs','dining_sessions','service_reviews'] LOOP EXECUTE format('CREATE POLICY license_gate ON public.%I AS RESTRICTIVE FOR ALL TO anon,authenticated USING (public.license_allows_operation()) WITH CHECK (public.license_allows_operation())',tbl); EXECUTE format('CREATE TRIGGER license_write_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_licensed_write()',tbl); END LOOP; END $$;
DO $$ DECLARE fn record; definition text; BEGIN FOR fn IN SELECT p.oid,p.proname,l.lanname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.proname IN ('set_order_status','track_order','claim_print','finish_print','requeue_print','demand_count','close_dining_session','submit_review','insert_club_order','submit_service_review','private_review_state') LOOP definition:=pg_get_functiondef(fn.oid); IF fn.lanname='plpgsql' THEN definition:=regexp_replace(definition,'\mBEGIN\M','BEGIN PERFORM public.assert_store_license();','i'); EXECUTE definition; ELSIF fn.lanname='sql' THEN definition:=replace(definition,'FROM public.orders WHERE','FROM public.orders WHERE public.license_allows_operation() AND '); EXECUTE definition; END IF; END LOOP; END $$;
ALTER TABLE public.store_settings ALTER COLUMN establishment_name SET DEFAULT 'FH Foods';